import{z as B,x as i,o,c as d,q as t,j as r,D as E,d as a,s as n,S as A,b as l}from"./chunks/framework.C8m1ZpeB.js";const v=JSON.parse('{"title":"BLAS 的层次","description":"","frontmatter":{"title":"BLAS 的层次","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-blas-levels.md","filePath":"cs/sc-blas-levels.md","lastUpdated":1791063341000}'),p={name:"cs/sc-blas-levels.md"};function m(c,e,f,C,D,h){const s=i("Mermaid");return o(),d("div",null,[e[2]||(e[2]=t('<h1 id="blas-的层次" tabindex="-1">BLAS 的层次 <a class="header-anchor" href="#blas-的层次" aria-label="Permalink to &quot;BLAS 的层次&quot;">​</a></h1><div class="epigraph"><p>矩阵运算的分类标准不是代数复杂度，而是每做一次浮点运算要搬多少字节；层次分的是访存账，不是数学。</p><footer>—— 据 Lawson et al., ACM TOMS, 1979；Dongarra et al., ACM TOMS, 1988 与 1990 整理</footer></div><p><a href="/cs/sc-float-deep">上一课</a>把 FMA 与 two-sum 钉成算法资源：舍入可以被集中、被消灭。本课把这份合同交给它最大的用户——稠密线性代数库。主干已给过 <a href="/cs/roofline-model">Roofline 模型</a>的算力带宽框架、<a href="/cs/simd-extensions">SIMD 扩展</a>的指令面与<a href="/cs/gaussian-pivoting">高斯消元与主元</a>的分解合同；缺口是：BLAS 为什么分三层、第三层为什么是所有稠密分解的速度来源、分层的代价又记在哪本账上。后课默认你能按层读任何线性代数调用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个 \\(C\\leftarrow C+AB\\)，朴素三重循环与分块实现可以差一个数量级；LU 若写成标量消元，编译器再努力也吃不满峰值。缺口不是「写得更巧」，而是把<strong>每 flop 搬运的字节数</strong>当一阶量：三层的差别全在这里。分不清层，优化就找错对象——给 level-2 的循环做向量化，收益封顶在带宽上，与指令集无关。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层各一个代表。Level 1 是向量运算：<code>axpy</code> 算 \\(y\\leftarrow y+\\alpha x\\)，\\(O(n)\\) 数据对 \\(O(n)\\) 运算，每 flop 搬两个数，被带宽钉死。Level 2 是矩阵向量：<code>gemv</code> 与秩一修正，\\(O(n^2)\\) 数据对 \\(O(n^2)\\) 运算，比值没变，仍是带宽问题——只是行主列主让带宽的利用率变得挑剔。Level 3 是矩阵矩阵：<code>gemm</code>，\\(O(n^2)\\) 的数据吃 \\(O(n^3)\\) 的运算，每 flop 搬运 \\(O(1/n)\\) 字节，瓶颈交还给算力，缓存分块让一块数据在寄存器与各级存储里复用。</p><p><span class="marginnote">把强度算出来：\\(n=1000\\) 的 <code>gemm</code> 做 \\(2n^3\\approx 2\\times10^9\\) 次 flop，只碰 \\(24\\) MB 数据，算术强度约 80 flop/字节；<code>axpy</code> 每 16 字节只做 2 次 flop，强度约 0.1。差三个数量级——这就是同一台机器上两层调用速度差几个数量级的来路。</span></p><p><span class="marginnote">「算术强度」就是每搬 1 字节数据能做几次浮点运算——它是判断一段代码「卡带宽还是卡算力」的尺子。强度低于机器的「平衡点」（flop 峰值 ÷ 带宽峰值）就是带宽瓶颈，优化方向是少搬数据而不是更快的乘法。</span></p><p><span class="marginnote">直觉类比：level-1 像一人一趟只拎一瓶水（搬一次用一次）；level-3 像整车运水到水塔再慢慢分（搬一次用很多次）。水塔（缓存）容量有限，所以要用「分块」控制每次运多少。</span></p><p>分层的真正兑现，是把分解改写成 level-3 调用：块 LU 把消元组织成「面板分解加三角乘与更新」，选主元仍按<a href="/cs/gaussian-pivoting">高斯消元与主元</a>的合同在面板上进行，其余工作量全部落进 <code>gemm</code>。这也解释了实现栈的分工：Netlib 参考版保证正确与可读，厂商库（MKL、BLIS、Accelerate）只在同一接口下换内核——接口是 1979 年钉下的，内核随 SIMD、FMA 与缓存层级改写。</p>',11)),(o(),r(A,null,{default:E(()=>[n(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22Level%201%EF%BC%9Aaxpy%EF%BC%8C%E6%AF%8F%20flop%20%E6%90%AC%E4%B8%A4%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20BW%5B%22%E5%B8%A6%E5%AE%BD%E7%93%B6%E9%A2%88%22%5D%0A%20%20L2%5B%22Level%202%EF%BC%9Agemv%EF%BC%8C%E6%AF%94%E5%80%BC%E4%B8%8D%E5%8F%98%22%5D%20--%3E%20BW%0A%20%20L3%5B%22Level%203%EF%BC%9Agemm%EF%BC%8C%E6%AF%8F%20flop%20%E6%90%AC%20O(1%2Fn)%22%5D%20--%3E%20COMP%5B%22%E7%AE%97%E5%8A%9B%E7%93%B6%E9%A2%88%EF%BC%9A%E5%88%86%E5%9D%97%E5%A4%8D%E7%94%A8%22%5D%0A%20%20COMP%20--%3E%20LU%5B%22%E5%9D%97%20LU%EF%BC%9A%E9%9D%A2%E6%9D%BF%E5%88%86%E8%A7%A3%E5%8A%A0%20gemm%20%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h2",{id:"机制",tabindex:"-1"},[a("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=l("p",null,[a("Level 3 为什么吃得满：分块后每个 \\(b\\) 见方的子块驻留缓存期间做完全部贡献，数据搬运从 \\(O(n^3)\\) 降到 \\(O(n^3/b)\\)，"),l("a",{href:"/cs/external-memory-model"},"外存算法与 I/O 模型"),a("早就给过这条下界的形状。「库比手写快」的结构原因在这里：不是编译器差异，是运算被重写成搬运输入更小的形式。")],-1)),e[5]||(e[5]=l("p",null,[a("代价记在数值账上。分块改变求和顺序，"),l("a",{href:"/cs/summation-order"},"求和顺序"),a("的界随重排变化；块 LU 与标量 LU 在浮点里不是同一条路径——残差都在 \\(\\gamma_n\\) 量级，比特却不再逐位一致。要复现就得固定分块与内核，这是上一课「合同」的延伸：精确块归调用方，运算组织归库，两头都要钉死。FMA 在内核里再省一次舍入，改变的是 \\(\\gamma_n\\) 的常数，不改 754 位型。")],-1)),(o(),r(A,null,{default:E(()=>[n(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22n%20%E9%98%B6%E7%9F%A9%E9%98%B5%E4%B9%98%22%5D%20--%3E%20BLK%5B%22%E6%8C%89%20b%20%E8%A7%81%E6%96%B9%E5%88%86%E5%9D%97%E8%A3%85%E5%85%A5%E7%BC%93%E5%AD%98%22%5D%0A%20%20BLK%20--%3E%20REUSE%7B%22%E6%AF%8F%E5%9D%97%E6%95%B0%E6%8D%AE%E9%A9%BB%E7%95%99%E7%BC%93%E5%AD%98%E6%9C%9F%E9%97%B4%22%7D%0A%20%20REUSE%20--%20%22%E5%81%9A%E6%BB%A1%20O(b%5E3)%20%E6%AC%A1%E4%B9%98%E5%8A%A0%22%20--%3E%20HITT%5B%22%E6%90%AC%E8%BF%90%E9%87%8F%E9%99%8D%E5%88%B0%20O(n%5E3%2Fb)%22%5D%0A%20%20REUSE%20--%20%22%E5%8F%AA%E5%81%9A%E4%B8%80%E6%AC%A1%E5%B0%B1%E6%8D%A2%E5%9D%97%22%20--%3E%20MISS%5B%22%E9%80%80%E5%8C%96%E6%88%90%20level-2%3A%20%E5%B8%A6%E5%AE%BD%E7%93%B6%E9%A2%88%22%5D%0A%20%20HITT%20--%3E%20L3%5B%22%E7%93%B6%E9%A2%88%E4%BA%A4%E8%BF%98%E7%AE%97%E5%8A%9B%2C%20%E5%90%83%E6%BB%A1%E5%B3%B0%E5%80%BC%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t('<p>这张图回答的问题是：<code>gemm</code> 吃满峰值的条件到底卡在哪——分块尺寸必须让子块「驻留期内做完全部贡献」，块太大装不进缓存、块太小退化成 level-2 的搬运模式，两头都掉速。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进具体内核的微架构，不把 LAPACK 驱动层（<code>gesv</code>、<code>potrf</code>）展开，只指出它建立在三层之上；GPU 上的布局与占用是另一门课的对象。稀疏矩阵没有这种红利——每行不定长、间接寻址让 <code>gemm</code> 式复用难产——那是下一课的对象。后课默认：见到稠密调用先问落在哪层，level-2 走不进峰值，也别指望它在峰值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三层的差别是每 flop 的搬运量：level-1 与 level-2 被带宽钉死，level-3 才轮到算力。</li><li>块分解把消元改写成面板加 gemm；主元合同不变，速度来自分块复用。</li><li>分块改舍入路径：残差量级不变，逐位复现要钉分块与内核。</li><li>参考版与厂商库共享接口，优化发生在内核，不发生在接口。</li><li>出处：Lawson et al., 1979；Dongarra et al., 1988 与 1990；Golub and Van Loan, Matrix Computations。</li></ul>',5))])}const g=B(p,[["render",m]]);export{v as __pageData,g as default};
